CREATE view RASID_ANBAR as  SELECT     dbo.HEAD_LST.NUMBER, dbo.HEAD_LST.TAG, dbo.HEAD_LST.DATE_N, dbo.HEAD_LST.CUST_NO, dbo.HEAD_LST.ANBAR, dbo.HEAD_LST.NUMBER1, dbo.HEAD_LST.TAH, dbo.HEAD_LST.MAS, dbo.HEAD_LST.VAS, dbo.HEAD_LST.N_S, dbo.HEAD_LST.M_NAGHD, dbo.HEAD_LST.MABL_VAR, dbo.HEAD_LST.MOIN_VAR, dbo.HEAD_LST.MABL_HAV, dbo.HEAD_LST.MOIN_HAV, dbo.HEAD_LST.MABL_HAZ, dbo.HEAD_LST.MOIN_HAZ, dbo.HEAD_LST.TAKHFIF, dbo.HEAD_LST.MOIN_KHF, dbo.HEAD_LST.ANBARF, dbo.HEAD_LST.FNUMCO, dbo.INVO_LST.NUMBER AS INUMBER, dbo.INVO_LST.TAG AS ITAG, dbo.INVO_LST.ANBAR AS IANBAR, dbo.INVO_LST.RADIF, dbo.INVO_LST.CODE, dbo.INVO_LST.MEGH, dbo.INVO_LST.MEGHk, dbo.INVO_LST.MEGH_MAR, dbo.INVO_LST.MANDAH, dbo.INVO_LST.MABL, dbo.INVO_LST.MABL_K, dbo.INVO_LST.FROM_A,  dbo.INVO_LST.N_RASID, dbo.INVO_LST.MEGH_R, dbo.INVO_LST.CUST_NO AS ICUST_NO, dbo.TCOD_ANBAR.NAMES, ISNULL(dbo.STUF_DEF.NAME, N' ') + N' ' + ISNULL(dbo.INVO_LST.MANDAH, N' ') AS KALA, dbo.TCOD_VAHEDS.NAMES AS VNAMES, dbo.HEAD_LST.MOLAH, dbo.HEAD_LST.USER_NAME, dbo.CUST_HESAB.hes, dbo.CUST_HESAB.NAME, dbo.CUST_HESAB.ADDRESS, dbo.STUF_DEF.N_FANI, dbo.HEAD_LST.SHARAYET, dbo.INVO_LST.VAHED_K, dbo.CUST_HESAB.TEL, dbo.OTHER_DTL.REQUEST_NO, dbo.OTHER_DTL.BARNAMEH, dbo.OTHER_DTL.DRIVER, dbo.OTHER_DTL.DRIVER_MOB, dbo.OTHER_DTL.CAMIUN_NUM, dbo.OTHER_DTL.MAGHSAD, dbo.OTHER_DTL.CAM_KHALY, dbo.OTHER_DTL.CAM_POOR, dbo.OTHER_DTL.TOZIH, dbo.OTHER_DTL.CAMIUN, dbo.OTHER_DTL_SUB.CAM_KHALY AS CAM_KHALYG, dbo.OTHER_DTL_SUB.CAM_POOR AS CAM_POORG,  dbo.OTHER_DTL_SUB.MEGHk AS MEGHkG, dbo.OTHER_DTL_SUB.TOZIH AS TOZIHG, dbo.OTHER_DTL_SUB.VAZNH, STUF_DEF_1.NAME AS NAMEG, dbo.OTHER_DTL_SUB.CODE AS CODEG,dbo.STUF_DEF.BARCODE, CUST_HESAB_1.NAME AS HESAB, dbo.SALA_DTL.EMZA AS EMZA1, SALA_DTL_2.EMZA AS EMZA2, SALA_DTL_1.EMZA AS EMZA3 FROM         dbo.SALA_DTL SALA_DTL_2 RIGHT OUTER JOIN dbo.SALA_DTL SALA_DTL_1 RIGHT OUTER JOIN dbo.STUF_DEF INNER JOIN dbo.TCOD_VAHEDS INNER JOIN dbo.HEAD_LST INNER JOIN dbo.INVO_LST ON dbo.HEAD_LST.NUMBER = dbo.INVO_LST.NUMBER AND dbo.HEAD_LST.TAG = dbo.INVO_LST.TAG ON dbo.TCOD_VAHEDS.CODE = dbo.INVO_LST.VAHED_K ON dbo.STUF_DEF.CODE = dbo.INVO_LST.CODE INNER JOIN dbo.TCOD_ANBAR ON dbo.INVO_LST.ANBAR = dbo.TCOD_ANBAR.CODE ON SALA_DTL_1.IDD = dbo.HEAD_LST.sgn3usid LEFT OUTER JOIN  dbo.CUST_HESAB CUST_HESAB_1 ON dbo.HEAD_LST.CUST_NO = CUST_HESAB_1.hes LEFT OUTER JOIN dbo.STUF_DEF STUF_DEF_1 INNER JOIN dbo.OTHER_DTL_SUB ON STUF_DEF_1.CODE = dbo.OTHER_DTL_SUB.CODE ON dbo.INVO_LST.NUMBER = dbo.OTHER_DTL_SUB.NUMBER AND dbo.INVO_LST.TAG = dbo.OTHER_DTL_SUB.TAGG AND dbo.INVO_LST.CODE = dbo.OTHER_DTL_SUB.CODE LEFT OUTER JOIN dbo.OTHER_DTL ON dbo.HEAD_LST.NUMBER = dbo.OTHER_DTL.NUMBER AND dbo.HEAD_LST.TAG = dbo.OTHER_DTL.TAG LEFT OUTER JOIN dbo.CUST_HESAB ON dbo.HEAD_LST.CUST_NO = dbo.CUST_HESAB.hes LEFT OUTER JOIN dbo.SALA_DTL ON dbo.HEAD_LST.sgn1usid = dbo.SALA_DTL.IDD ON SALA_DTL_2.IDD = dbo.HEAD_LST.sgn2usid 
